contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking parameters for target and amount
    function run(address target, uint256 mintedAmount) public payable {
        require(target != address(0)); // avoid trivial zero-address transfer/reverts due to checks elsewhere

        // read before-values
        uint256 beforeBalance = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;

        // attempt the mint and detect revert
        bool reverted;
        c.mintToken(target, mintedAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        uint256 afterBalance = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;

        // Assert the general rule: if mint succeeded, both balance and totalSupply increased by mintedAmount;
        // if it reverted, neither changed.
        assert((!reverted && afterBalance == beforeBalance + mintedAmount && afterTotal == beforeTotal + mintedAmount) || (reverted && afterBalance == beforeBalance && afterTotal == beforeTotal));
    }

    receive() external payable {}
}

