        c = new ERCDDAToken(0, "", "");
    }

    function _run(address target, uint256 mintedAmount) internal {
        vm.assume(target != address(0));
        uint256 beforeBalance;
        try c.balanceOf(target) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint256 beforeTotal;
        try c.totalSupply() returns (uint256 __r) { beforeTotal = __r; } catch { return; }
        bool reverted;
        try c.mintToken(target, mintedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
